import { Readable } from 'node:stream'

/**
 * A running Studio HTTP server.
 */
export interface StudioServer {
  /**
   * Shuts the server down and stops accepting new connections.
   */
  close(): void
}

export interface StartStudioServerOptions {
  /**
   * Handles an incoming request and produces the response to send back.
   */
  handler: (request: Request) => Response | Promise<Response>

  /**
   * Invoked once the server is ready to accept connections.
   */
  onListen: () => void

  /**
   * The port to listen on.
   */
  port: number
}

/**
 * Starts an HTTP server that delegates incoming requests to `handler`.
 *
 * `HEAD` requests are answered with the status of the equivalent `GET` response
 * but an empty body. If `handler` throws, the server responds with HTTP 500 and
 * the error message as a plain-text body.
 */
export function startStudioServer({ handler, onListen, port }: StartStudioServerOptions): StudioServer {
  const server = createServer((req, res) => {
    void handleRequest(req, res, handler)
  })

  server.listen(port, () => {
    onListen()
  })

  return {
    close() {
      server.close()
    },
  }
}

async function handleRequest(
  req: IncomingMessage,
  res: ServerResponse,
  handler: (request: Request) => Response | Promise<Response>,
): Promise<void> {
  const isHead = req.method === 'HEAD'

  let response: Response

  try {
    response = await handler(toWebRequest(req, isHead ? 'GET' : (req.method ?? 'GET')))
  } catch (error) {
    console.error('[Prisma Studio]', error)

    const message = error instanceof Error ? error.message : String(error)

    res.writeHead(500, {
      'access-control-allow-origin': '*',
      'content-type': 'text/plain; charset=utf-8',
    })
    res.end(isHead ? undefined : message)
    return
  }

  const headers: Record<string, string> = {}
  response.headers.forEach((value, key) => {
    headers[key] = value
  })

  res.writeHead(response.status, headers)

  if (isHead || response.body === null) {
    res.end()
    return
  }

  Readable.fromWeb(response.body as Parameters<typeof Readable.fromWeb>[0]).pipe(res)
}

function toWebRequest(req: IncomingMessage, method: string): Request {
  const url = `http://${req.headers.host ?? 'localhost'}${req.url ?? '/'}`

  const headers = new Headers()
  for (const [key, value] of Object.entries(req.headers)) {
    if (value === undefined) {
      continue
    }

    if (Array.isArray(value)) {
      for (const item of value) {
        headers.append(key, item)
      }
    } else {
      headers.set(key, value)
    }
  }

  const init: RequestInit = { method, headers }

  if (method !== 'GET' && method !== 'HEAD') {
    init.body = Readable.toWeb(req) as ReadableStream<Uint8Array>
    // Required by the fetch spec when a request carries a streaming body.
    ;(init as RequestInit & { duplex: 'half' }).duplex = 'half'
  }

  return new Request(url, init)
}
